window.MG_LAZY_DATA["data/lazy/owner-courses/c213-500487042324b27c.json"]={sha256:"500487042324b27c8945939fcbc717a6b5639d16ac7b44aa0ea74efba24e3b0f",value:{"id":"c213","title":"Toyota Prius 油電混合車","titleEn":"Toyota Prius hybrid vehicle","category":"automotive","summary":"從公開THS架構出發，用能量帳、理想齒輪、回生與儲能例題理解Prius油電整合，並練習公平比較不同駕駛與世代條件。","summaryEn":"Start from the public THS architecture and use energy balances, ideal gearing, regeneration and storage exercises to understand Prius hybrid integration and fair comparisons.","scope":"12道原創概念任務；1997與2003資料僅用於架構及歷史。數值不是任何Prius的ECU標定、電池規格或制動設定；不進行高壓系統拆裝或車輛改裝。","scopeEn":"Twelve original conceptual tasks; 1997 and 2003 sources support architecture and history. Values are not Prius ECU calibration, battery specifications or brake settings. No high-voltage disassembly or vehicle modification.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-prius-ths","v6-prius-2003","v6-toyota-kaikan"],"diagram":{"type":"car","labels":["燃油與引擎","功率分流","電池與電機","車輪與制動","能量與熱帳"],"labelsEn":["Fuel and engine","Power split","Battery and machines","Wheels and braking","Energy and heat balance"],"original":true,"notToScale":true},"depth":4,"stages":[{"id":"c213-stage01","order":1,"title":"能量邊界與分流原理","titleEn":"Energy boundaries and power-split principles","description":"先畫能量流，再以功率、時間和理想速度約束檢查單位與邊界。","descriptionEn":"Map energy flows, then check units and boundaries through power, time and ideal speed constraints.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c213-v6-01","order":1,"sequence":1,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":[],"sourceIds":["v6-prius-ths"],"title":"界定油電系統的能量邊界","titleEn":"Define the hybrid energy boundary","objective":"辨識燃油、電池、車輪功與熱的能量角色。","objectiveEn":"Identify the energy roles of fuel, battery, wheel work and heat.","instruction":"畫燃油、引擎、發電機、電池、馬達與車輪方塊。以箭頭連接可能能量流，另畫散熱出口；比較行程時保留電池起終儲能，避免把回生當成新能量來源。","instructionEn":"Draw fuel, engine, generator, battery, motor and wheel blocks. Connect possible energy paths and add heat exits. Retain initial and final battery energy when comparing trips, rather than treating regeneration as a new energy source.","observation":"電池可在不同時刻吸收或釋放能量，其起終差影響比較。","observationEn":"The battery can absorb or release energy at different times; its net change affects comparisons.","failure":"只看燃油消耗，卻忽略行程結束時電池少了能量，會偏估效率。","failureEn":"Comparing fuel alone while ignoring a depleted battery biases the efficiency assessment.","check":"圖上有能量輸入、儲存、有用輸出與損失四類。","checkEn":"Show energy input, storage, useful output and losses.","knowledge":[{"id":"c213-v6-01-k1","title":"能量守恆","titleEn":"Energy conservation","text":"能量轉換會改變形式，回生不會憑空創造能量。","textEn":"Conversion changes energy form; regeneration does not create energy."},{"id":"c213-v6-01-k2","title":"比較邊界","titleEn":"Comparison boundary","text":"相同行程也要比較電池儲能變化，才有一致邊界。","textEn":"Even equal trips require battery-energy changes to establish a consistent boundary."}],"quiz":{"question":"哪項必須納入兩次行程的公平能量比較？","questionEn":"What must be included for a fair energy comparison between two trips?","options":["只比較燃油消耗，即使電池終點不同","把回生當成系統外新增的能量輸入","電池起點與終點的儲能差"],"optionsEn":["Compare fuel alone even when final battery states differ","Treat regeneration as new energy entering from outside the system","The initial-to-final battery-energy change"],"answer":2,"explanation":"電池能量差代表行程使用或留下的儲能。","explanationEn":"Battery-energy change represents stored energy used or retained by the trip."}},{"id":"c213-v6-02","order":2,"sequence":2,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-01"],"sourceIds":["v6-prius-ths"],"title":"把功率曲線換成能量","titleEn":"Convert a power profile into energy","objective":"用時間積分分清kW與kWh。","objectiveEn":"Separate kW and kWh through time integration.","instruction":"使用虛構輪端需求：10kW維持6分鐘、20kW維持3分鐘。各自換算小時後求能量，再畫等能量但不同峰值的另一條曲線。","instructionEn":"Use fictional wheel demand of 10 kW for 6 minutes and 20 kW for 3 minutes. Convert time to hours, calculate each energy and sketch another profile with equal energy but a different peak.","observation":"兩段各1kWh，總計2kWh；峰值與累積量不同。","observationEn":"Each interval is 1 kWh, totaling 2 kWh; peak and accumulation differ.","failure":"把分鐘直接乘上kW卻標成kWh，會產生60倍單位錯誤。","failureEn":"Multiplying minutes by kW and labeling the result kWh creates a factor-of-60 error.","check":"每段保留時間換算，總面積為2kWh。","checkEn":"Retain each time conversion and obtain a total area of 2 kWh.","knowledge":[{"id":"c213-v6-02-k1","title":"功率積分","titleEn":"Power integration","text":"固定功率下E=Pt，變動功率則累加分段面積。","textEn":"For constant power E=Pt; varying power requires summing interval areas."},{"id":"c213-v6-02-k2","title":"峰值需求","titleEn":"Peak demand","text":"相同總能量仍可能需要不同的峰值供能能力。","textEn":"Equal total energy can require different peak power capability."}],"quiz":{"question":"20kW維持3分鐘的能量是多少？","questionEn":"How much energy is 20 kW sustained for 3 minutes?","options":["0.15kWh","1kWh","60kWh"],"optionsEn":["0.15 kWh","1 kWh","60 kWh"],"answer":1,"explanation":"3分鐘是0.05小時，20×0.05=1。","explanationEn":"Three minutes is 0.05 hours; 20×0.05=1."}},{"id":"c213-v6-03","order":3,"sequence":3,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-02"],"sourceIds":["v6-prius-ths"],"title":"畫出功率分流的两條路徑","titleEn":"Draw two power-split paths","objective":"區分機械傳遞與電力轉換路徑。","objectiveEn":"Distinguish mechanical transmission from electrical conversion.","instruction":"參照Toyota公開系統圖，原創重畫引擎到車輪的機械路徑及經發電機、電力系統、馬達的路徑。再畫電池可接入的位置，不把某次分流比例寫成固定常數。","instructionEn":"Using Toyota’s public system diagram as a reference, redraw the engine-to-wheel mechanical path and the path through generator, electrical system and motor. Add the battery connection without treating one power split as a fixed ratio.","observation":"車輪可由不同能量路徑共同驅動，路徑需隨情境辨識。","observationEn":"Different energy paths can contribute to wheel drive and must be identified by scenario.","failure":"把所有引擎能量都畫成先進電池，混淆功率分流與純串聯系統。","failureEn":"Routing all engine energy through the battery confuses power splitting with a purely series system.","check":"兩條路徑都可從引擎追蹤到車輪，電池為儲能分支。","checkEn":"Trace both paths from engine to wheels, showing the battery as storage.","knowledge":[{"id":"c213-v6-03-k1","title":"分流裝置","titleEn":"Power-split device","text":"公開THS架構把引擎功率分配到機械與發電路徑。","textEn":"The public THS architecture distributes engine power between mechanical and generation paths."},{"id":"c213-v6-03-k2","title":"轉換損失","titleEn":"Conversion loss","text":"經過不同轉換次數的路徑，損失與限制不一定相同。","textEn":"Paths with different conversion stages need not have equal losses or limits."}],"quiz":{"question":"哪張圖較符合公開THS分流概念？","questionEn":"Which diagram better matches the public THS power-split concept?","options":["引擎同時可連向車輪及發電機","引擎所有能量都必須先存入電池","引擎僅機械驅動車輪，電機僅用於起動"],"optionsEn":["The engine can connect toward both wheels and generator","All engine energy must first be stored in the battery","The engine only drives mechanically and the electrical machine only starts it"],"answer":0,"explanation":"功率分流包含機械路徑，不是所有能量都必經電池。","explanationEn":"Power splitting includes a mechanical path; not all energy must pass through the battery."}},{"id":"c213-v6-04","order":4,"sequence":4,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-03"],"sourceIds":["v6-prius-ths"],"title":"閱讀行星齒輪的速度約束","titleEn":"Read a planetary-gear speed constraint","objective":"理解三個轉速並非可任意獨立選擇。","objectiveEn":"Understand that three rotational speeds are not independent.","instruction":"用理想教學齒輪關係(Ns+Nr)ωc=Nsωs+Nrωr，假設Ns=1、Nr=2，令ωs=0、ωr=3，求ωc。圖上只標太陽輪、環齒輪及行星架，不聲稱這是任一Prius的齒數。","instructionEn":"Use the ideal teaching relation (Ns+Nr)ωc=Nsωs+Nrωr with Ns=1, Nr=2, ωs=0 and ωr=3. Solve for ωc. Label sun, ring and carrier without claiming these are Prius tooth counts.","observation":"三項轉速受同一幾何關係約束，結果ωc=2。","observationEn":"The three speeds share one kinematic constraint, giving ωc=2.","failure":"把三個轉速各自任意設置，通常無法同時符合齒輪嚙合關係。","failureEn":"Arbitrarily choosing all three speeds generally violates the gear constraint.","check":"將結果代回等式，左右兩側皆為6。","checkEn":"Substitute the result and obtain 6 on both sides.","knowledge":[{"id":"c213-v6-04-k1","title":"運動約束","titleEn":"Kinematic constraint","text":"齒輪嚙合限制相對運動，不等於固定所有軸的轉速比例。","textEn":"Gear engagement constrains relative motion without fixing every shaft-speed ratio."},{"id":"c213-v6-04-k2","title":"模型層級","titleEn":"Model level","text":"理想速度方程未包含損失、控制器或實際零件限制。","textEn":"An ideal speed equation excludes losses, controllers and actual component limits."}],"quiz":{"question":"此例的行星架轉速ωc為多少？","questionEn":"What is the carrier speed ωc in this example?","options":["3","6","2"],"optionsEn":["3","6","2"],"answer":2,"explanation":"3ωc=1×0+2×3，故ωc=2。","explanationEn":"3ωc=1×0+2×3, so ωc=2."}}]},{"id":"c213-stage02","order":2,"title":"駕駛情境與儲能變化","titleEn":"Driving scenarios and stored energy","description":"使用虛構加速、制動與儲能案例，避免把效率、功率和能量混為一談。","descriptionEn":"Use fictional acceleration, braking and storage cases to distinguish efficiency, power and energy.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c213-v6-05","order":1,"sequence":5,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-04"],"sourceIds":["v6-prius-ths"],"title":"核對加速時的瞬時功率帳","titleEn":"Check an acceleration power balance","objective":"辨識多來源供能與轉換損失。","objectiveEn":"Identify multiple power contributions and conversion losses.","instruction":"設教學時刻輪端需30kW，引擎路徑提供18kW、電池經馬達提供15kW。計算總輸入與差額，將差額列為簡化損失項；不要當作車輛效率實測。兩項功率是同一共同邊界的上游輸入，假設邊界內儲能不變且無其他功率流。","instructionEn":"At a teaching instant, assume wheel demand is 30 kW, with 18 kW from an engine path and 15 kW from a battery/motor path. Calculate total input and the residual as a simplified loss term, not measured vehicle efficiency. Both inputs cross the same system boundary; assume no change in stored energy inside that boundary and no other power flows.","observation":"供能33kW與輪端30kW之間有3kW差額。","observationEn":"There is a 3 kW residual between 33 kW supplied and 30 kW at the wheels.","failure":"把不同介面量到的功率直接當同一位置，會重複計算或漏算損失。","failureEn":"Treating power measured at different interfaces as one location can double-count or omit losses.","check":"各功率標清量測邊界，帳目以同一時刻平衡。","checkEn":"Label the boundary for each power and balance one instant consistently.","knowledge":[{"id":"c213-v6-05-k1","title":"瞬時平衡","titleEn":"Instantaneous balance","text":"功率帳必須對應相同時刻與清楚的系統邊界。","textEn":"A power balance requires the same instant and clear system boundaries."},{"id":"c213-v6-05-k2","title":"殘差判讀","titleEn":"Residual interpretation","text":"帳目差可能代表損失、儲能變化或量測不一致，需先定義模型。","textEn":"A residual may represent loss, storage change or inconsistent measurement; define the model first."}],"quiz":{"question":"在已定義的簡化例題中，損失項是多少？","questionEn":"In this defined simplified example, what is the loss term?","options":["63kW","3kW","12kW"],"optionsEn":["63 kW","3 kW","12 kW"],"answer":1,"explanation":"18+15−30=3kW。","explanationEn":"18+15−30=3 kW."}},{"id":"c213-v6-06","order":2,"sequence":6,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-05"],"sourceIds":["v6-prius-ths"],"title":"比較效率點與整體油耗","titleEn":"Compare operating efficiency with trip fuel use","objective":"避免把引擎最佳效率點當作永遠可用的答案。","objectiveEn":"Avoid treating an engine’s best-efficiency point as always available.","instruction":"自畫兩個假設運轉點：A的需求10、效率0.25，B的需求20、效率0.40。比較輸入需求P/η，再列出多餘能量是否可儲存及何時需要它；不使用OEM效率圖。","instructionEn":"Invent operating points A with output 10 and efficiency 0.25, and B with output 20 and efficiency 0.40. Compare input P/η, then ask whether surplus energy can be stored and when it is needed. Use no OEM efficiency map.","observation":"效率較高的B，其瞬時輸入仍可能較大。","observationEn":"The more efficient point B can still have higher instantaneous input.","failure":"只看效率百分比而忽略需求與儲能限制，會選錯比較邊界。","failureEn":"Looking only at efficiency percentage ignores demand and storage constraints.","check":"列出A輸入40、B輸入50，以及不能直接比較全程油耗的原因。","checkEn":"Report inputs of 40 and 50 and explain why they do not directly compare trip fuel use.","knowledge":[{"id":"c213-v6-06-k1","title":"效率定義","titleEn":"Efficiency definition","text":"效率是有用輸出與輸入的比值，不是輸入的絕對大小。","textEn":"Efficiency is useful output divided by input, not the absolute input magnitude."},{"id":"c213-v6-06-k2","title":"時間協調","titleEn":"Time coordination","text":"混合動力可跨時間安排能量，但仍受儲能與損失限制。","textEn":"A hybrid can coordinate energy over time, subject to storage and loss constraints."}],"quiz":{"question":"較高效率點一定消耗較少瞬時輸入嗎？","questionEn":"Does a higher-efficiency point always use less instantaneous input?","options":["不一定，還要看輸出需求","一定，只要效率百分比較高","只要兩點的時間相同就一定較少"],"optionsEn":["No; output demand also matters","Yes, whenever its efficiency percentage is higher","Yes, as long as both points last equally long"],"answer":0,"explanation":"輸入等於輸出除以效率，兩個量都影響結果。","explanationEn":"Input equals output divided by efficiency, so both quantities matter."}},{"id":"c213-v6-07","order":3,"sequence":7,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-06"],"sourceIds":["v6-prius-ths"],"title":"分析回生制動的能量上限","titleEn":"Analyze an energy limit for regeneration","objective":"區分可回收動能與实际儲存能量。","objectiveEn":"Distinguish recoverable kinetic energy from stored energy.","instruction":"以E=mv²/2比較同質量在v與2v時的動能。假設某次減速有100教學能量單位、總回收比例0.6，求儲存與未回收部分；這不是真車制動設定。","instructionEn":"Use E=mv²/2 to compare kinetic energy at v and 2v for equal mass. For a fictional slowdown with 100 energy units and a total recovery fraction of 0.6, calculate stored and unrecovered portions. This is not a brake setting.","observation":"速度加倍使動能成4倍；例題只能存回60單位。","observationEn":"Doubling speed quadruples kinetic energy; the example stores only 60 units.","failure":"把每次制動的全部動能都算入電池，忽略轉換與接收限制。","failureEn":"Counting all braking energy as battery storage ignores conversion and acceptance limits.","check":"能量帳為60回收加40未回收，且不超過100。","checkEn":"Show 60 recovered plus 40 unrecovered, never exceeding 100.","knowledge":[{"id":"c213-v6-07-k1","title":"動能平方律","titleEn":"Kinetic-energy square law","text":"質量固定時，動能與速度平方成正比。","textEn":"At fixed mass, kinetic energy is proportional to speed squared."},{"id":"c213-v6-07-k2","title":"回收限制","titleEn":"Recovery limits","text":"電池接收能力、系統損失與行駛情境限制回生。","textEn":"Battery acceptance, system losses and driving conditions limit regeneration."}],"quiz":{"question":"同質量速度加倍，動能變為多少倍？","questionEn":"For the same mass, doubling speed multiplies kinetic energy by what?","options":["2倍","1/2倍","4倍"],"optionsEn":["2","1/2","4"],"answer":2,"explanation":"動能包含v²項。","explanationEn":"Kinetic energy contains v²."}},{"id":"c213-v6-08","order":4,"sequence":8,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-07"],"sourceIds":["v6-prius-ths"],"title":"追蹤電池儲能狀態","titleEn":"Track battery stored-energy state","objective":"把充放電事件排成可核對的能量序列。","objectiveEn":"Arrange charge/discharge events into an auditable energy sequence.","instruction":"假設可用儲能窗10單位，起始6；先放出2，再接收1.2。計算各時刻存量並對照0至10示意範圍；不把百分比當成真實電池電壓。","instructionEn":"Assume a usable 10-unit storage window starting at 6. Discharge 2, then receive 1.2. Compute each state within the teaching range 0–10, without equating a percentage to actual battery voltage.","observation":"最終為5.2，與起點差−0.8。","observationEn":"The final state is 5.2, a change of −0.8 from the start.","failure":"用總充電量當最終存量，會漏掉初始條件與放電。","failureEn":"Using total charge received as final stored energy omits the initial state and discharge.","check":"列出6→4→5.2，能量增減與每個事件一致。","checkEn":"Show 6→4→5.2 with changes matching each event.","knowledge":[{"id":"c213-v6-08-k1","title":"狀態量","titleEn":"State variable","text":"儲能取決於初始狀態與之後累積的能量變化。","textEn":"Stored energy depends on the initial state and accumulated changes."},{"id":"c213-v6-08-k2","title":"估計與量測","titleEn":"Estimation and measurement","text":"電池狀態估計不能僅靠任意單一百分比推回完整物理狀態。","textEn":"A battery-state estimate cannot be reconstructed fully from an arbitrary percentage alone."}],"quiz":{"question":"例題行程結束，比起點少多少儲能？","questionEn":"How much stored energy is lost relative to the start in this example?","options":["5.2單位","0.8單位","1.2單位"],"optionsEn":["5.2 units","0.8 units","1.2 units"],"answer":1,"explanation":"6−5.2=0.8。","explanationEn":"6−5.2=0.8."}}]},{"id":"c213-stage03","order":3,"title":"熱、功能與比較證據","titleEn":"Heat, function and comparison evidence","description":"從熱帳與回生受限情境走向條件一致、版本明確的工程比較。","descriptionEn":"Move from heat balance and limited regeneration to comparisons with matched conditions and explicit versions.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c213-v6-09","order":1,"sequence":9,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-08"],"sourceIds":["v6-prius-ths"],"title":"建立損失到散熱的路徑","titleEn":"Trace losses into thermal management","objective":"把電力與機械損失連到熱負荷。","objectiveEn":"Connect electrical and mechanical losses to heat loads.","instruction":"在原創能量圖上標出馬達、電力轉換與電池的假設損失位置。使用簡化熱帳：產熱8單位、散熱5單位，標示內能增加方向；不指定真車冷卻液或溫度。","instructionEn":"Mark hypothetical motor, power-conversion and battery losses on your energy diagram. Use a simplified heat balance with 8 units generated and 5 removed, indicating the direction of internal-energy change. Specify no vehicle coolant or temperature.","observation":"持續產熱大於散熱時，儲存熱能會增加。","observationEn":"Stored thermal energy increases when generation persistently exceeds removal.","failure":"只查瞬時電功率而忽略時間累積，可能漏掉熱負荷。","failureEn":"Checking instantaneous electrical power alone can miss accumulated thermal loading.","check":"寫出+3單位內能變化，並指出還缺熱容量才能估溫升。","checkEn":"Record +3 units of internal-energy change and identify heat capacity as needed for temperature rise.","knowledge":[{"id":"c213-v6-09-k1","title":"熱平衡","titleEn":"Thermal balance","text":"產熱、散熱與儲熱需同時納入。","textEn":"Generation, removal and storage all belong in the heat balance."},{"id":"c213-v6-09-k2","title":"模型不足","titleEn":"Model incompleteness","text":"沒有熱容量與邊界條件，不能由能量差直接得溫度。","textEn":"Without heat capacity and boundary conditions, an energy difference does not determine temperature."}],"quiz":{"question":"產熱8、散熱5，能否直接知道溫度？","questionEn":"With generation 8 and removal 5, can temperature be known directly?","options":["不能，尚需熱容量等條件","能，必定是3°C","能，必定維持不變"],"optionsEn":["No; heat capacity and other conditions are needed","Yes, it must be 3°C","Yes, it must stay unchanged"],"answer":0,"explanation":"能量差與溫度差的單位和意義不同。","explanationEn":"Energy difference and temperature difference have different units and meanings."}},{"id":"c213-v6-10","order":2,"sequence":10,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-09"],"sourceIds":["v6-prius-ths"],"title":"分析回生受限時的制動需求","titleEn":"Analyze braking demand when regeneration is limited","objective":"分開處理車輛減速需求與能量回收能力。","objectiveEn":"Separate required deceleration from energy-recovery capability.","instruction":"在紙上列出假設減速需求與可用回生兩欄。安排一個電池暫不能接收能量的情境，指出總制動功能仍需由合格整車系統滿足；僅做功能分析，不改制動控制。","instructionEn":"On paper, list hypothetical deceleration demand and available regeneration. Introduce a battery-unavailable-for-charging scenario and identify that overall braking must still be met by the qualified vehicle system. Analyze functions only; do not alter brake control.","observation":"回生降低不代表駕駛的減速需求同時消失。","observationEn":"Reduced regeneration does not remove the driver’s braking demand.","failure":"把回收能量視為唯一制動能力，會混淆安全功能與效率功能。","failureEn":"Treating recovery as the sole braking capability confuses safety and efficiency functions.","check":"列出能量回收、總減速及狀態提示三項不同需求。","checkEn":"List energy recovery, total deceleration and status indication as distinct requirements.","knowledge":[{"id":"c213-v6-10-k1","title":"功能協調","titleEn":"Functional coordination","text":"多種制動作用需在整車層級協調驗證。","textEn":"Different braking contributions require vehicle-level coordination and verification."},{"id":"c213-v6-10-k2","title":"受限狀態","titleEn":"Limited availability","text":"能量儲存的限制可能改變回收能力。","textEn":"Storage constraints can change recovery capability."}],"quiz":{"question":"電池不能接收回生能量時，仍須满足什麼？","questionEn":"When the battery cannot accept regenerated energy, what remains necessary?","options":["保持與電池可充電時完全相同的回收量","把回生能力當成唯一總制動需求","整車規定的減速功能"],"optionsEn":["Maintain exactly the same recovery as when charging was available","Treat regeneration capability as the sole overall braking requirement","The vehicle’s required deceleration function"],"answer":2,"explanation":"效率功能受限不能取代總制動需求。","explanationEn":"A recovery limitation does not replace the overall braking requirement."}},{"id":"c213-v6-11","order":3,"sequence":11,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-10"],"sourceIds":["v6-prius-ths","v6-prius-2003"],"title":"設計公平的行程比較","titleEn":"Design a fair trip comparison","objective":"控制影響油耗比較的條件。","objectiveEn":"Control conditions that affect fuel-use comparisons.","instruction":"自製兩次虛構行程紀錄欄位：距離、速度歷程、坡度、載重、環境與電池起終狀態。找出其中一項不一致時應如何限制結論；不自填真實油耗數據。","instructionEn":"Create fields for two fictional trips: distance, speed profile, grade, payload, environment and initial/final battery state. Explain how a mismatch in one field limits conclusions, without inventing measured fuel data.","observation":"相同距離並不保证相同交通、載荷或能量邊界。","observationEn":"Equal distance does not guarantee equal traffic, load or energy boundaries.","failure":"把不同測試循環的公開數字直接排名，可能比較的是條件而非技術。","failureEn":"Ranking numbers from different test cycles may compare conditions rather than technology.","check":"列出至少三個需一致的條件及一項仍存在的不確定性。","checkEn":"List at least three conditions to match and one remaining uncertainty.","knowledge":[{"id":"c213-v6-11-k1","title":"實驗控制","titleEn":"Experimental control","text":"比較需要限定變動因素，並記錄無法控制的因素。","textEn":"Comparison requires limiting changing factors and recording uncontrolled ones."},{"id":"c213-v6-11-k2","title":"重複性","titleEn":"Repeatability","text":"單次結果不足以描述變動範圍。","textEn":"A single result does not describe variability."}],"quiz":{"question":"兩次行程距離相同，就能直接比較技術效率嗎？","questionEn":"Are equal trip distances enough to compare technical efficiency directly?","options":["只要車款名稱相同就能","不能，還需匹配其他條件與能量邊界","能，距離是唯一因素"],"optionsEn":["Only matching the model name is needed","No; other conditions and energy boundaries must match","Yes; distance is the only factor"],"answer":1,"explanation":"公平比較涉及負载、速度、環境與儲能狀態。","explanationEn":"A fair comparison involves load, speed, environment and stored-energy state."}},{"id":"c213-v6-12","order":4,"sequence":12,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c213-v6-11"],"sourceIds":["v6-prius-ths","v6-prius-2003","v6-toyota-kaikan"],"title":"交付分世代的油電證據圖","titleEn":"Deliver a generation-specific hybrid evidence map","objective":"區分跨世代原理與某一車型的具體實作。","objectiveEn":"Separate cross-generation principles from model-specific implementation.","instruction":"把1997公開THS架構與2003 THS II發表放在时间線。將本課程的能量守恆、分流、回生和熱帳標為可轉移原理；把硬體數值及控制標定列為需按年份查證。","instructionEn":"Place the 1997 public THS architecture and 2003 THS II announcement on a timeline. Mark conservation, power splitting, regeneration and heat balance as transferable principles; mark hardware values and control calibration for model-year verification.","observation":"名字延續不代表每代的電池、電機與控制設定相同。","observationEn":"A continuing model name does not mean identical batteries, machines or controls across generations.","failure":"將一代技術資料與另一代型號混在同一張表而未標年分，會造成錯引。","failureEn":"Mixing one generation’s technical data with another model without dates creates misattribution.","check":"提交有來源年份、假設標記與待查欄位的系統圖。","checkEn":"Submit a system map with source years, assumption labels and open verification fields.","knowledge":[{"id":"c213-v6-12-k1","title":"技術傳承","titleEn":"Technical continuity","text":"物理原理可延續，工程實作仍會演進。","textEn":"Physical principles can persist while implementation evolves."},{"id":"c213-v6-12-k2","title":"版本溯源","titleEn":"Version provenance","text":"年份、市場與產品版本是技術資料的一部分。","textEn":"Year, market and product revision are part of technical provenance."}],"quiz":{"question":"閱讀不同世代Prius資料，哪種做法最好？","questionEn":"What is the best practice when reading different Prius generations?","options":["標明年份與版本再比較相同功能","所有資料合併為一套固定參數","以較新的照片證明舊規格"],"optionsEn":["Mark year and revision before comparing the same function","Merge all data into one fixed parameter set","Use a newer photo to prove an older specification"],"answer":0,"explanation":"版本明確，才不會將架構原理誤當固定實作。","explanationEn":"Explicit versions prevent confusing architectural principles with fixed implementation."}}]}],"stepCount":12,"estimatedMinutes":216,"languageCoverage":["zh-TW","en"],"status":"guided","kind":"course","curriculumVersion":6}};
